        const {
            team_ids,
            venue_id,
            event_type,
            start_date,
            end_date,
            page = 1,
            limit = 50
        } = req.query;

        let query = supabase
            .from('events')
            .select(`
                *,
                venues(name, address),
                event_teams(team_id, teams(id, name))
            `)
            .order('start_time', { ascending: true });

        // Apply filters
        if (team_ids) {
            const teamIdsArray = Array.isArray(team_ids) ? team_ids : [team_ids];
            // Filter events that have any of the specified teams
            query = query.in('event_teams.team_id', teamIdsArray);
        }

        if (venue_id) {
            query = query.eq('venue_id', venue_id);
        }

        if (event_type) {
            query = query.eq('event_type', event_type);
        }

        if (start_date) {
            query = query.gte('start_time', start_date);
        }

        if (end_date) {
            query = query.lte('start_time', end_date);
        }

        // Apply pagination
        const offset = (parseInt(page) - 1) * parseInt(limit);
        query = query.range(offset, offset + parseInt(limit) - 1);

        const { data, error } = await query;

        // Get count separately for pagination
        let countQuery = supabase
            .from('events')
            .select('id', { count: 'exact', head: true });

