// Supported field types
const SUPPORTED_FIELD_TYPES = [
    'text', 'email', 'number', 'tel', 'url', 'password',
    'textarea', 'select', 'checkbox', 'radio', 'date',
    'datetime-local', 'time', 'file', 'hidden'
