                            first_name: '',
                            last_name: '',
                            email: '',
                            phone: '',
                            date_of_birth: '',
                            gender: '',
                            emergency_contact_name: '',
                            emergency_contact_phone: '',
                            emergency_contact_relation: '',
                            medical_alerts: '',
                            address: ''
                          })
                          setRegistrationNotes('')
                          setRegistrationResult(null)
                        }}
                      >
                        Register Another Player
                      </Button>
                      <Button onClick={() => window.location.href = '/'}>
                        Return to Home
