        res.status(200).json({
            forms: forms || [],
            pagination: {
                page: parseInt(page),
                limit: parseInt(limit),
                total: count,
                totalPages: Math.ceil(count / parseInt(limit))
            }
        });
    } catch (error) {
        console.error('Get forms error:', error);
        res.status(500).json({ error: 'Internal server error' });
    }
});

