        const { data: field, error } = await supabase
            .from('form_fields')
            .insert([{
                form_id,
                field_name,
                field_label: label,
                field_type,
                is_required,
                default_value: default_value || null,
                placeholder_text: placeholder || null,
                sort_order: order_index || 0,
                validation_rules: validation_regex ? { regex: validation_regex } : null
            }])
            .select(`
                *,
                form_field_options (
                    id,
                    option_label,
                    option_value,
