// POST /api/payments/create-intent - Create Stripe payment intent with enhanced error handling
app.post('/api/payments/create-intent', authenticateUser, async (req, res) => {
    const { amount, currency = 'usd', program_registration_id } = req.body;

    // Enhanced input validation
    if (!amount || !program_registration_id) {
        return res.status(400).json({
            error: 'amount and program_registration_id are required',
            error_code: 'missing_required_fields'
        });
    }

    // Validate amount with more strict checks
    if (typeof amount !== 'number' || amount <= 0 || amount > 999999) {
        return res.status(400).json({
            error: 'amount must be a positive number between $0.01 and $9,999.99',
            error_code: 'invalid_amount'
        });
    }

    // Validate currency
    const supportedCurrencies = ['usd'];
    if (!supportedCurrencies.includes(currency.toLowerCase())) {
        return res.status(400).json({
            error: `Currency ${currency} is not supported. Supported currencies: ${supportedCurrencies.join(', ')}`,
            error_code: 'unsupported_currency'
        });
    }

    try {
        // Verify the registration exists and validate payment eligibility
        const { data: registration, error: regError } = await supabase
            .from('program_registrations')
            .select(`
                *,
                programs (id, name, base_fee),
                users (id, email)
            `)
            .eq('id', program_registration_id)
            .single();

        if (regError || !registration) {
            return res.status(404).json({
                error: 'Registration not found',
                error_code: 'registration_not_found'
            });
        }

        // Verify user owns this registration
        if (registration.user_id !== req.user.id) {
            return res.status(403).json({
                error: 'Unauthorized access to registration',
                error_code: 'unauthorized_registration'
            });
        }

        // Calculate balance due to ensure payment amount is valid
        const totalAmountDue = parseFloat(registration.total_amount_due || registration.programs?.base_fee || 0);
        const amountPaid = parseFloat(registration.amount_paid || 0);
        const balanceDue = totalAmountDue - amountPaid;

        if (balanceDue <= 0) {
            return res.status(400).json({
                error: 'No payment required - registration is already paid in full',
                error_code: 'no_payment_required',
                balance_due: 0
            });
        }

        if (amount > balanceDue) {
            return res.status(400).json({
                error: `Payment amount ($${amount.toFixed(2)}) exceeds balance due ($${balanceDue.toFixed(2)})`,
                error_code: 'amount_exceeds_balance',
                balance_due: balanceDue
            });
        }

        // Create payment intent with Stripe with enhanced metadata and security
        const paymentIntentOptions = {
            amount: Math.round(amount * 100), // Convert to cents
            currency: currency.toLowerCase(),
            automatic_payment_methods: {
                enabled: true
            },
            metadata: {
                program_registration_id,
                user_id: req.user.id.toString(),
                user_email: registration.users?.email || 'unknown',
                program_name: registration.programs?.name || 'Unknown Program',
                environment: process.env.NODE_ENV || 'development'
            },
            description: `Payment for ${registration.programs?.name || 'Program'} registration`,
            statement_descriptor: 'GamePlan Pro',
            receipt_email: registration.users?.email
        };

        const paymentIntent = await stripe.paymentIntents.create(paymentIntentOptions);

        // Log payment intent creation for audit trail (without sensitive data)
        console.log('Payment intent created:', {
            payment_intent_id: paymentIntent.id,
            amount: amount,
            currency: currency,
            registration_id: program_registration_id,
            user_id: req.user.id,
            timestamp: new Date().toISOString()
        });

        res.json({
            client_secret: paymentIntent.client_secret,
            payment_intent_id: paymentIntent.id,
            amount: amount,
            currency: currency,
            description: paymentIntentOptions.description
        });

    } catch (error) {
        const errorInfo = handlePaymentError(error, 'create_payment_intent');

        // Log error for monitoring
        console.error('Create payment intent failed:', {
            user_id: req.user?.id,
            registration_id: program_registration_id,
            amount: amount,
            error_type: errorInfo.error_type,
            error_code: errorInfo.error_code
        });

        res.status(500).json({
            error: errorInfo.user_message,
            error_code: errorInfo.error_code,
            error_type: errorInfo.error_type,
            should_retry: errorInfo.should_retry
        });
    }
});

