                venues(name, address),
                event_teams(team_id, teams(id, name))
            `)
            .order('start_time', { ascending: true });

        // Apply filters
        if (team_ids) {
            const teamIdsArray = Array.isArray(team_ids) ? team_ids : [team_ids];
