                organization: team.organization
            })) : []
        }));

        // Generate response based on format
        switch (format) {
            case 'json':
                res.json({
                    data: formattedData,
                    metadata: {
                        total_contacts: formattedData.length,
                        team_filter: teamIds.length > 0 ? teamIds : 'all',
                        generated_at: new Date().toISOString()
                    }
                });
                break;

            case 'csv':
