        }

        res.json({
            roster_entries: data,
            pagination: {
                page: parseInt(page),
                limit: parseInt(limit),
                total: count,
                pages: Math.ceil(count / parseInt(limit))
            }
        });
    } catch (error) {
        console.error('Get roster entries error:', error);
        res.status(500).json({ error: 'Internal server error' });
    }
});

