                            if (isNaN(Number(value))) {
                                isValid = false;
                                typeError = 'Must be a valid number';
                            }
                            break;
                        case 'date':
                            if (isNaN(Date.parse(value))) {
                                isValid = false;
                                typeError = 'Must be a valid date';
                            }
