    standardHeaders: true,
    legacyHeaders: false,
    handler: (req, res) => {
        console.warn(`Auth rate limit exceeded for IP: ${req.ip}, Path: ${req.path}`);
        res.status(429).json({
            error: 'Too many authentication attempts. Please wait before trying again.',
            retryAfter: 15 * 60
        });
    }
});

