                stripe_payment_intent_id: paymentIntent.id,
                program_registration_id,
                amount,
                currency: currency.toLowerCase(),
                status: 'pending',
                created_at: new Date().toISOString(),
                metadata: {
                    request_id: requestId,
                    stripe_client_secret: paymentIntent.client_secret,
