                    'Organization': team.organization,
                    'Description': team.description,
                    'Division': team.division,
                    'Age Group': team.age_group,
                    'Skill Level': team.skill_level,
                    'Active Player Count': team.active_player_count
                }));

                // Convert to CSV format
