                    id,
                    option_label,
                    option_value,
                    sort_order
                )
            `)
            .eq('form_id', form_id)
            .order('sort_order', { ascending: true });

        if (fieldsError) {
            console.error('Form fields fetch error:', fieldsError);
            return res.status(500).json({ error: 'Failed to fetch form fields' });
        }

        res.status(200).json({
            ...form,
