            // Delete existing fields
            await supabase
                .from('form_fields')
                .delete()
                .eq('form_id', form_id);

            // Insert new fields
            if (fields.length > 0) {
                const fieldsToInsert = fields.map((field, index) => ({
                    form_id,
                    field_name: field.field_name,
                    field_label: field.field_label,
                    field_type: field.field_type,
                    is_required: field.is_required || false,
