            .from('form_fields')
            .select('id')
            .eq('form_id', form_id)
            .eq('field_name', field_name)
            .single();

        if (existingField) {
            return res.status(409).json({
                error: 'A field with this name already exists in this form'
            });
        }

        // Create the form field
        const { data: field, error } = await supabase
            .from('form_fields')
            .insert([{
                form_id,
                field_name,
                field_label: label,
                field_type,
                is_required,
                default_value: default_value || null,
                placeholder_text: placeholder || null,
                sort_order: order_index || 0,
                validation_rules: validation_regex ? { regex: validation_regex } : null
            }])
            .select(`
                *,
                form_field_options (
                    id,
                    option_label,
                    option_value,
                    sort_order
                )
            `)
            .single();

        if (error) {
            console.error('Field creation error:', error);
            return res.status(500).json({ error: 'Failed to create field' });
        }

        res.status(201).json({
            message: 'Field created successfully',
